    sysbus_init_irq(SYS_BUS_DEVICE(dev), &s->irq_u_passthrough_mbyte_cnt);
    s->ptimer_u_passthrough_mbyte_cnt = ptimer_init(spi_device_tick_u_passthrough_mbyte_cnt, s, PTIMER_POLICY_LEGACY);
    ptimer_transaction_begin(s->ptimer_u_passthrough_mbyte_cnt);
    ptimer_set_freq(s->ptimer_u_passthrough_mbyte_cnt, SPI_DEVICE_PTIMER_FREQ);
    ptimer_transaction_commit(s->ptimer_u_passthrough_mbyte_cnt);
    sysbus_init_irq(SYS_BUS_DEVICE(dev), &s->irq_u_spi_tpm_cmdaddr_bitcnt);
    s->ptimer_u_spi_tpm_cmdaddr_bitcnt = ptimer_init(spi_device_tick_u_spi_tpm_cmdaddr_bitcnt, s, PTIMER_POLICY_LEGACY);
    ptimer_transaction_begin(s->ptimer_u_spi_tpm_cmdaddr_bitcnt);
    ptimer_set_freq(s->ptimer_u_spi_tpm_cmdaddr_bitcnt, SPI_DEVICE_PTIMER_FREQ);
    ptimer_transaction_commit(s->ptimer_u_spi_tpm_cmdaddr_bitcnt);
    sysbus_init_irq(SYS_BUS_DEVICE(dev), &s->irq_u_spi_tpm_isck_fifoaddr);
